using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    public string Category { get; set; } = string.Empty;

    [Required, MinLength(1)]
    public List<string> Ingredients { get; set; } = new();

    [Required, MinLength(1)]
    public List<string> Steps { get; set; } = new();

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one ingredient is required.")]
    [MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one step is required.")]
    [MinLength(1, ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = new() { "Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt" },
                Steps = new() { "Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and drizzle olive oil." },
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = new() { "Spaghetti", "Guanciale", "Egg yolks", "Pecorino Romano", "Black pepper" },
                Steps = new() { "Cook spaghetti in salted boiling water.", "Crisp guanciale in a pan.", "Whisk egg yolks with grated pecorino and pepper.", "Toss hot pasta with guanciale.", "Remove from heat and stir in egg mixture.", "Serve immediately with extra pecorino." },
                AverageRating = 4.8, RatingCount = 20
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = new() { "Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger" },
                Steps = new() { "Marinate chicken in yogurt and spices for 2 hours.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer 15 minutes.", "Stir in cream and cooked chicken.", "Simmer 10 minutes and serve with rice." },
                AverageRating = 4.6, RatingCount = 15
            },
            new()
            {
                Id = 4, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = new() { "Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning" },
                Steps = new() { "Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in oven.", "Assemble tacos with beef and toppings.", "Serve with salsa and sour cream." },
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Ingredients = new() { "Rice noodles", "Shrimp", "Egg", "Bean sprouts", "Green onion", "Peanuts", "Tamarind paste", "Fish sauce", "Lime" },
                Steps = new() { "Soak rice noodles in warm water 30 minutes.", "Make sauce: mix tamarind, fish sauce, and sugar.", "Stir-fry shrimp until pink, set aside.", "Scramble egg in the wok.", "Add noodles and sauce, toss until coated.", "Add shrimp, bean sprouts, and peanuts. Serve with lime." },
                AverageRating = 4.4, RatingCount = 10
            },
            new()
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Ingredients = new() { "Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Salt", "Tomato" },
                Steps = new() { "Halve and pit avocados, scoop into bowl.", "Mash to desired consistency.", "Stir in lime juice, diced onion, cilantro, and jalapeño.", "Fold in diced tomato.", "Season with salt and serve with chips." },
                AverageRating = 4.7, RatingCount = 18
            },
        };
        _nextId = 7;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        };
        _recipes.Add(recipe);
    }
}

